-- practice_texts_pt.lua and practice_texts_es.lua.
return {
    ["0C9Uxfvh.d"] = "If the pawn is on the fifth or sixth rank, there are six key squares: the square in front of the pawn and the squares to the left and right, as well as the square two squares in front of the pawn, and the squares to the left and right of it. Reach a key square with your king and win.",
    ["0C9Uxfvh.n"] = "Pawn on the 6th rank",
    ["0JTf6FMY.d"] = "In the Vukovic Mate, a rook and knight team up to mate the king on the edge of the board. The rook delivers mate while supported by a third piece, and the knight is used to block the king's escape squares.",
    ["0JTf6FMY.n"] = "Vukovic Mate #1",
    ["11V1Hkyr.d"] = "The attraction is a tactic that occurs when we force an opponent's piece to move to a bad square. “Decoy” is also a synonym to attraction.",
    ["11V1Hkyr.n"] = "Attraction #1",
    ["17CE1GKS.c0"] = "Since the Black king is not on one of the red squares, we know this is a win for White. Let's win this game by playing the only winning move .",
    ["17CE1GKS.c1"] = "We are now threatening to promote. However, Black can't play Rxa7 due to Rh7+, winning the rook on a7. The best Black can do is to delay the eventual loss.",
    ["17CE1GKS.c11"] = "We are now threatening a8=Q, so Black has to give up their Rook.",
    ["17CE1GKS.c2"] = "We move towards the promotion square",
    ["17CE1GKS.d"] = "In this Study, we're going to look at Rook endgames where both sides have a Rook, but one side has a pawn on the 7th-rank and their Rook is passive, or \"trapped\", in front of the pawn.\n\nIf Black's King is on any of the red squares when it's White to move, this position is a draw.\n\nWith Black's King on b6 or b7, Black will simply capture the pawn on the next move.\n\nWith Black's King on c6 or c7, Black will play Kb7 on the next move and be able to either capture the pawn or occupy the promotion square by playing Ka8.\n\nWith Black's King on a1, a2, or a6, it's impossible for White to move their Rook away from the promotion square with tempo as no checks are available. White either has to move their Rook and lose the pawn, or move their King. The White King has nowhere to hide, so black can just check White forever.\n\nIf the black King is on any square other than the red squares, it is a win for White.\n\nWith Black's King on d7, e7 or f7, White can play Rh8. Black can't respond with Rxa7 due to Rh7+, winning the rook on a7. The best Black can do is to delay the eventual loss.\n\nWith Black's King on any other square not mentioned, White can move their Rook away from the promotion square with a check and promote their pawn on the next move.",
    ["17CE1GKS.n"] = "King on f7",
    ["17sHdtD6.d"] = "When trying to checkmate with two bishops, there are two important principles to follow. One, the bishops are best when they are near the center of the board and on adjacent diagonals. This cuts off the opposing king. Two, the king must be used aggressively, in conjunction with the bishops.\n\nMate in 13 if played perfectly.",
    ["17sHdtD6.n"] = "Two bishop mate",
    ["1BGkV2oq.d"] = "From Samuel Reshevsky - George Shainswit, 1951.",
    ["1BGkV2oq.n"] = "Morphy's Mate #3",
    ["1BRP8nqF.d"] = "Damiano's Mate is a classic method of checkmating and one of the oldest. It works by confining the king with a pawn or bishop and using a queen to initiate the final blow. Damiano's mate is often arrived at by first sacrificing a rook on the h-file, then checking the king with the queen on the h-file, and then moving in for the mate. The checkmate was first published by Pedro Damiano in 1512.",
    ["1BRP8nqF.n"] = "Damiano's Mate #1",
    ["1QlAUVRV.d"] = "From Emil Joseph Diemer - Portz, 1948.",
    ["1QlAUVRV.n"] = "Boden's Mate #3",
    ["1hqMrfIx.d"] = "Although the Pawn Mate can take many forms, it is generally characterized as a mate in which a pawn is the final attacking piece and where enemy pawns are nearby. The Pawn Mate is sometimes also called the David and Goliath Mate, named after the biblical account of David and Goliath.",
    ["1hqMrfIx.n"] = "Pawn Mate #1",
    ["1u8PEnNu.c1"] = "Correct! We're pushing the King back so that we can invade with Kf8.",
    ["1u8PEnNu.c2"] = "And now?",
    ["1u8PEnNu.c3"] = "Correct! We invade with our King to further restrict Black.",
    ["1u8PEnNu.h0"] = "You want to push the Black King back in order to invade with your King. There is only one move that does this here.",
    ["1u8PEnNu.n"] = "Exercise: Restricting the King to the Second Triangle",
    ["1u8PEnNu.v1"] = "That move does not push the Black King towards the queenside.",
    ["3A6bWZtO.d"] = "Richard Reti - Savielly Tartakower, 1910.",
    ["3A6bWZtO.n"] = "Attraction #2",
    ["3VN6nGzy.d"] = "From Loek van Wely - Alexander Morozevich, 2001.",
    ["3VN6nGzy.n"] = "Epaulette Mate #2",
    ["4DsOTJ1h.d"] = "Use your knowledge of Zugzwang to promote one of your pawns safely.",
    ["4DsOTJ1h.n"] = "Zugzwang #3",
    ["4vQVBOaV.c0"] = "For rook endings with a rook pawn, as long as the king is 3 files away from the enemy pawn the ending is holdable because Black's king can make it in time to the crucial c7 square when white tries to bring the rook to the b-file to make a bridge. It is important to keep white's king obstructing the pawn with our rook on the b-file.\n\nMove the rook to b3 to continue the exercise.",
    ["4vQVBOaV.c10"] = "Now we need to move our king in a way that white's king will not be able to leave the promotion square to the pawn. Note here that white will not be able to move the king if we move to the d6 or c6 square because of checkmate.",
    ["4vQVBOaV.c2"] = "White hasn't made any progress, so we can keep moving our rook on the b-file. Play Rb2.",
    ["4vQVBOaV.c4"] = "Now white is trying to get to the b-file with Rh8-Rb8. Play Kd7 to bring the king to c7 on time.",
    ["4vQVBOaV.c8"] = "White brought the rook to the b-file, but the king is still obstructing the pawn. Exchanging the rooks here is obviously losing because white can recapture while promoting the pawn. Therefore we need to move our rook to any other file (except the a- and c-file).",
    ["4vQVBOaV.n"] = "Holding Against a Rook Pawn",
    ["5AR69ul5.d"] = "If the pawn is on the second, third, or fourth rank, there are three key squares: the square two squares in front of the pawn and the squares to the left and right of that square. Reach a key square with your king and win.",
    ["5AR69ul5.n"] = "Pawn on the 4th rank",
    ["5OqFMeoY.c0"] = "You will have to use all of your pieces to push Black's king to a corner. Black will first try to stay in the center. Continue the lesson by moving your King towards the center.",
    ["5OqFMeoY.c10"] = "Take away the g6 square from Black.",
    ["5OqFMeoY.c12"] = "Get your Knight in the game.",
    ["5OqFMeoY.c14"] = "Move your Knight closer.",
    ["5OqFMeoY.c16"] = "In this phase of the endgame, your King belongs on f6 where it controls g7, while leaving both f7 and g6 for your Knight.",
    ["5OqFMeoY.c18"] = "The Knight is the only piece that can force the King out of the wrong corner. Force the Black King out of hiding!",
    ["5OqFMeoY.c2"] = "Black is also moving towards the center.",
    ["5OqFMeoY.c20"] = "The Black King only has one square. Pass the move in order to force Kg8!",
    ["5OqFMeoY.c22"] = "Take away the h7 square in order to force Kf8 - only move!",
    ["5OqFMeoY.c24"] = "Now we can maneuver our Knight safely to the correct position for the first triangle.",
    ["5OqFMeoY.c28"] = "Get your last piece into the perfect square to complete the first triangle!",
    ["5OqFMeoY.c29"] = "Nice work! The King is now restricted to the first triangle. Notice how we control all the red squares.",
    ["5OqFMeoY.c4"] = "Occupy the center.",
    ["5OqFMeoY.c6"] = "White now controls the center. When Black can't stay in the center, they will usually try to move towards the wrong corner (h8 in this case). This looks like a good opportunity to get your Bishop into the game.",
    ["5OqFMeoY.c8"] = "Take away the f6 square from Black.",
    ["5OqFMeoY.n"] = "Restricting the King to the First Triangle",
    ["5OqFMeoY.w11.c4f7"] = "Giving up your bishop means you won't have enough material to win and the game is now a draw :-(",
    ["5lIa27XB.c0"] = "A frontal defense is best used when the pawn has not advanced to the 5th rank. Despite the Black king being two files away from the passed pawn, the game is still salvageable. Black survives by giving a barrage of checks, preventing the white king from making progress.\n\nFirst, we need to prevent white from playing b5 right away.",
    ["5lIa27XB.c13"] = "White can't make any progress. The game will eventually end in a draw.",
    ["5lIa27XB.c2"] = "Now, we can start the sequence of checks and white will not be able to do anything.",
    ["5lIa27XB.c9"] = "White has no options but to defend the pawn.",
    ["5lIa27XB.n"] = "Frontal Defense",
    ["69N0EC11.d"] = "From R Schulder - Samuel Standidge Boden, 1853.",
    ["69N0EC11.n"] = "Boden's Mate #2",
    ["6HQvRyz0.d"] = "In Anastasia's Mate, a knight and rook team up to trap the opposing king between the side of the board on one side and a friendly piece on the other. This checkmate got its name from the novel \"Anastasia und das Schachspiel\" by Johann Jakob Wilhelm Heinse.",
    ["6HQvRyz0.n"] = "Anastasia's Mate #1",
    ["6RaFYVig.d"] = "From Joseph Henry Blackburne - Alexander Steinkuehler, 1871.",
    ["6RaFYVig.n"] = "Lolli's Mate #3",
    ["7TeHHvJd.d"] = "From Adolf Anderssen - Max Lange, 1859.",
    ["7TeHHvJd.n"] = "Max Lange's Mate #2",
    ["807Ghffh.d"] = "Normally the winning process involves the queen first winning the rook by a fork and then checkmating with the king and queen, but forced checkmates with the rook still on the board are possible in some positions or against incorrect defense.\n\nMate in 18 if played perfectly.",
    ["807Ghffh.n"] = "Queen vs rook mate",
    ["8Chn1bVb.d"] = "A Double Check is when two pieces are delivering check simultaneously. A Double Check is generally more powerful than a normal check, because the opponent can only respond with a king move. (The pieces that are delivering check cannot both be captured or blocked with one move.)",
    ["8Chn1bVb.n"] = "Double Check Introduction",
    ["8K8FdT6P.d"] = "Use your rooks to restrict the king and deliver checkmate. Mate in 4 if played perfectly.",
    ["8K8FdT6P.n"] = "Two rook mate",
    ["8TJF17dT.c0"] = "Play the only drawing move for White to get to the relevant position we are discussing.",
    ["8TJF17dT.c10"] = "If we can't promote our pawn, we stay on, or next to, the corner square with our King. Any legal move draws for White.",
    ["8TJF17dT.c12"] = "Only one legal move. We keep shuffling.",
    ["8TJF17dT.c13"] = "Threatening to promote.",
    ["8TJF17dT.c14"] = "One wrong step and you lose instantly!",
    ["8TJF17dT.c15"] = "Threatening to promote.",
    ["8TJF17dT.c16"] = "If allowed, we promote our pawn to force the draw.",
    ["8TJF17dT.c2"] = "Black tries to get their Queen closer. Multiple moves holds a draw for White, but if we can't promote our pawn, we should put our King on, or next to, the corner square.",
    ["8TJF17dT.c3"] = "Note that many moves are an immediate draw by stalemate for Black.",
    ["8TJF17dT.c4"] = "Black tries to get closer. We just stay next to the corner square. Either legal move is fine for White.",
    ["8TJF17dT.c5"] = "We are now threatening to promote.",
    ["8TJF17dT.c6"] = "If we can't promote our pawn, we stay on, or next to, the corner square with our King.",
    ["8TJF17dT.c8"] = "Only one legal move. We keep shuffling.",
    ["8TJF17dT.c9"] = "Threatening to promote.",
    ["8TJF17dT.d"] = "If the pawn on the 7th rank is a Bishop or Rook pawn, and the side with the Queen does not have their King near the pawn, the side with the pawn can draw.\n\nWhen it's a Rook pawn, the side with the pawn just needs to promote it if allowed, or otherwise keep their King in or near the corner. The side with the Queen won't have any time to get their King closer.",
    ["8TJF17dT.n"] = "Rook pawn, no King assistance = Draw",
    ["8TJF17dT.w15.b7a8"] = "This allows mate in 1!",
    ["9CYWkR3I.d"] = "Of the basic checkmates, this is the most difficult one to force, because the knight and bishop cannot form a linear barrier to the enemy king from a distance. The checkmate can be forced only in a corner that the bishop controls. The mating process often requires accurate play, since a few errors could result in a draw either by the fifty-move rule or stalemate.\n\nMate in 10 if played perfectly.",
    ["9CYWkR3I.n"] = "Knight and bishop mate #1",
    ["9rd7XwOw.d"] = "A Back-Rank Mate is a checkmate delivered by a rook or queen along the back rank in which the mated king is unable to move up the board because the king is blocked by friendly pieces (usually pawns) on the second rank.",
    ["9rd7XwOw.n"] = "Back-Rank Mate #1",
    ["9rnbKpVG.d"] = "An advanced rook pawn generally has two key squares: the two squares on the adjacent file that touch the promotion square. Reach a key square with your king and win.",
    ["9rnbKpVG.n"] = "Rook pawn #1",
    ["AK0BVMvm.d"] = "In Légal's Mate, the knight moves into a position to check the king. The bishop is guarded by the other knight, and the enemy pieces block the king's escape.",
    ["AK0BVMvm.n"] = "Légal's Mate #1",
    ["APLob5jh.d"] = "From Zaven Andriasian - Brent Burg, 2013.",
    ["APLob5jh.n"] = "Arabian Mate #2",
    ["AknfDdxO.d"] = "In this ending, the key idea for white to win is to bring the rook to the b8 square before the black king can get to c7 with the purpose of removing black's rook from the b-file. Then white can remove the king from the promotion square to promote the pawn successfully while avoiding checks and being careful if there's a checkmate. Good luck!",
    ["AknfDdxO.n"] = "Rook and Rook Pawn versus Rook",
    ["AtP03RHM.d"] = "Use your queen and knight to restrict the king and deliver checkmate. Mate in 5 if played perfectly.",
    ["AtP03RHM.n"] = "Queen and knight mate",
    ["Bkajq8eY.c0"] = "An extra g-pawn does not help White, but an extra b-, c-, d-, e-, or f-pawn does win for White. Why? Because we can now force Black's King away from g7 and h7.",
    ["Bkajq8eY.c5"] = "Kh7 loses due to f7 followed by f8=Q.\nKxf6 loses due to Rf8+ followed by a8=Q.\nRxf6 loses due to Rb8 followed by a8=Q.\nWhat happens after Kf7?",
    ["Bkajq8eY.c6"] = "With Black's King off g7 and h7, we can exploit the skewer as before.",
    ["Bkajq8eY.c7"] = "Note that Kxf6 would lose to the skewer Rh6+, winning the Rook on a6.",
    ["Bkajq8eY.c8"] = "Play the skewer we have seen before.",
    ["Bkajq8eY.n"] = "King on g7, extra b-f pawn",
    ["BvGvw8oy.d"] = "Zandor Nilsson - Efim Geller, 1954.",
    ["BvGvw8oy.n"] = "X-Ray #5",
    ["BzTG7OaQ.d"] = "The Hook Mate involves the use of a rook, knight, and pawn along with one blockading piece to limit the opponent's king's escape. In this mate, the rook is protected by the knight and the knight is protected by the pawn.",
    ["BzTG7OaQ.n"] = "Hook Mate #1",
    ["CKsYe1xR.d"] = "From Gregory Kaidanov - Viswanathan Anand, 1987.",
    ["CKsYe1xR.n"] = "Arabian Mate #3",
    ["CQybY5NW.d"] = "This looks like the previous chapter except for one important detail: the king now has access to the a-file. Through a series of maneuvers White will succeed in pushing the pawn to c5 and eventually win. Prove it!",
    ["CQybY5NW.n"] = "When the Frontal Defense doesn't work",
    ["CU2ErkDp.d"] = "This position is winning since the g5 pawn shields the king from checks!",
    ["CU2ErkDp.n"] = "Making Use of the Umbrella",
    ["CvzYQtQ1.d"] = "From Irina Andrenko - Olga Kalinina, 2007.",
    ["CvzYQtQ1.n"] = "Anastasia's Mate #4",
    ["D23EYigW.c0"] = "The first step is to restrict Black's King to one of the green triangles we see on the board in this position. We will control the long diagonal of the triangle with our Bishop, and we will control the necessary dark squares using our Knight and King.\n\nMove your King closer to the center to read about step 2 in the overall plan.",
    ["D23EYigW.c2"] = "When Black's King has been restricted to the first triangle, the second step is to further restrict it to a smaller second triangle (marked in green).\nMove your King closer to the center to read about step 3 in the overall plan.",
    ["D23EYigW.c4"] = "When Black's King has been restricted to the second triangle, the third step is to further restrict it to a smaller third triangle (marked in green), in which we will be able to set up the checkmate.",
    ["D23EYigW.c5"] = "Now you know the overall plan. In the next chapter we'll see a famous example of what can happen if you don't know this endgame.",
    ["D23EYigW.d"] = "In this Study, we will look at how to checkmate a lone King with a Knight and Bishop.\n\nThe first thing to note, is that we can only checkmate the King in the corner of the board which is the same color as our Bishop, which in this example is a8 and h1. If we had a dark squared Bishop, we could only checkmate Black on a1 or h8.\n\nBlack will therefore try to stay in the center of the board, and if they can't, then they will move towards the \"wrong\" corner, meaning a corner in which we can't checkmate the King.\n\nWhite however, wants to force Black's King to a8 or h1. To accomplish this, there are two well-known methods that can be used. One is called \"Delétang's triangle method\" and the other is called \"the W method\". You only have to know one of these methods. In this Study, we will learn the first one.\n\nThe basic idea is to restrict Black's King to smaller and smaller areas of the board.",
    ["D23EYigW.n"] = "Introduction",
    ["D2gPUFyM.d"] = "A variation in Aron Nimzowitsch - Bjorn Nielsen, 1930 that was not played.",
    ["D2gPUFyM.n"] = "Morphy's Mate #2",
    ["DHYwTmn2.d"] = "If the pawn on the 7th rank is a Bishop pawn, and the side with the Queen has their King on one of the green squares on their move, they can win the game.\n\nThe side with the Queen can allow the pawn to promote and deliver checkmate. When both Kings are on the long side, the attacker can accomplish this by having their King on one of the orange squares (f3, f2, f1) when the pawn promotes.",
    ["DHYwTmn2.n"] = "Exercise: Bishop pawn, defending King on long side, King assistance on long side",
    ["DTvC1FS9.d"] = "There are multiple winning moves for white in this position, but use the attraction tactic to checkmate the opponent in 3 moves.",
    ["DTvC1FS9.n"] = "Attraction #7",
    ["DhXGZctw.c0"] = "In this interesting position, the main idea for black to be able to draw is to not obstruct the pawn on the a-file and be cut off by white's rook. Thus black always needs to put their king on the c-file if white check them with the rook on the b-file.",
    ["DhXGZctw.c10"] = "White is still attempting to drive the king to a1.",
    ["DhXGZctw.c17"] = "As you saw, white wasn't able to make any progress.",
    ["DhXGZctw.c2"] = "White is trying to win the pawn. Black can defend it with only one move.",
    ["DhXGZctw.c4"] = "White is attempting to drive black's king to the a-file once again.",
    ["DhXGZctw.c5"] = "We keep moving our king on the c1 and b2 squares to keep the pawn. White hasn't made any progress. Now if white goes Ra7 and Rb7+ again, the game would end in a draw due to threefold repetition.",
    ["DhXGZctw.c6"] = "Now obviously Kd1 loses due to Ra7 or Kb3 and the pawn would be lost.",
    ["DhXGZctw.n"] = "Rook vs Pawn Draw",
    ["DhXGZctw.w15.a2a1r"] = "Also leads to a draw but promote to a queen to complete the exercise.",
    ["EAfC0cJn.d"] = "In this position, the King is on a7 instead of a8 which means you must checkmate Black slightly differently. Mate in three.",
    ["EAfC0cJn.n"] = "Exercise: Delivering Mate",
    ["EiaJcoV6.d"] = "From Zsuzsa Markhot - Sanja Arslanagic, 1997.",
    ["EiaJcoV6.n"] = "Back-Rank Mate #4",
    ["F0ghmuZq.d"] = "The Epaulette Mate is a checkmate where two parallel retreat squares for a checked king are occupied by its own pieces, preventing its escape.",
    ["F0ghmuZq.n"] = "Epaulette Mate #1",
    ["G2OeEr3o.d"] = "If the pawn is on the fifth or sixth rank, there are six key squares: the square in front of the pawn and the squares to the left and right, as well as the square two squares in front of the pawn, and the squares to the left and right of it. Reach a key square with your king and win.",
    ["G2OeEr3o.n"] = "Pawn on the 5th rank",
    ["G4XKY6pN.c0"] = "We have a passed pawn, but where should the rook be placed?",
    ["G4XKY6pN.c2"] = "Bring your rook to a1.",
    ["G4XKY6pN.c3"] = "Rooks are better behind passed pawns than in front of them because they don't obstruct and block the path of the pawn.",
    ["G4XKY6pN.n"] = "Don't Place the Cart Before the Horse!",
    ["G4xdAsQl.c0"] = "As before, we check the King and attack the pawn at the same time",
    ["G4xdAsQl.c10"] = "Force the black King to block their own pawn or to step away from it.",
    ["G4xdAsQl.c12"] = "Threaten the pawn.",
    ["G4xdAsQl.c14"] = "Check the King and attack the pawn at the same time.",
    ["G4xdAsQl.c16"] = "Bring the King closer.",
    ["G4xdAsQl.c18"] = "Pin the pawn.",
    ["G4xdAsQl.c19"] = "Note that Ka1 would be losing for Black in this position, as it allows White to get their Queen in front of the pawn.",
    ["G4xdAsQl.c2"] = "Black is taking advantage of the fact that Qxc2 would be an immediate draw by stalemate. Note that Black is now threatening to promote.",
    ["G4xdAsQl.c20"] = "Force the black King to block their own pawn or to step away from it.",
    ["G4xdAsQl.c22"] = "Threaten the pawn.",
    ["G4xdAsQl.c24"] = "Check the King and attack the pawn at the same time.",
    ["G4xdAsQl.c25"] = "Ka1 would draw as we saw before.",
    ["G4xdAsQl.c26"] = "Bring the King closer.",
    ["G4xdAsQl.c28"] = "Pin the pawn.",
    ["G4xdAsQl.c30"] = "Force the black King to block their own pawn or to step away from it.",
    ["G4xdAsQl.c32"] = "Threaten the pawn.",
    ["G4xdAsQl.c34"] = "Check the King and attack the pawn at the same time.",
    ["G4xdAsQl.c36"] = "Bring the King closer.",
    ["G4xdAsQl.c38"] = "Pin the pawn.",
    ["G4xdAsQl.c39"] = "Ka1 would lose for Black here, because White would play Kc3 and be able to capture the pawn.",
    ["G4xdAsQl.c4"] = "Check the King and attack the pawn at the same time.",
    ["G4xdAsQl.c40"] = "Force the black King to block their own pawn or to step away from it.",
    ["G4xdAsQl.c42"] = "Threaten the pawn.",
    ["G4xdAsQl.c44"] = "Check the King and attack the pawn at the same time.",
    ["G4xdAsQl.c45"] = "Now, Black can't afford to continue as normal anymore. After Kc1, White would play Kd3 and be able to capture the pawn with mate to follow. Black has to play Ka1 to draw.",
    ["G4xdAsQl.c46"] = "Again, Qxc2 is an immediate draw by stalemate. White can try to other moves, but won't be successful.",
    ["G4xdAsQl.c47"] = "Only one legal move for Black.",
    ["G4xdAsQl.c48"] = "Pin the pawn.",
    ["G4xdAsQl.c49"] = "Ka2 loses to Qxc2. Kc1 loses to Kc3 which will win the pawn. Ka1 draws because the pawn can only be captured with stalemate. Kb2 also draws, which we will see later.",
    ["G4xdAsQl.c50"] = "Can we try covering the promotion square?",
    ["G4xdAsQl.c51"] = "Black threatens to promote.",
    ["G4xdAsQl.c52"] = "White does not get a free move.",
    ["G4xdAsQl.c53"] = "Kc1 would lose because it gives White a free move to bring the King closer.",
    ["G4xdAsQl.c54"] = "Promotion is threatened again.",
    ["G4xdAsQl.c56"] = "If the game is not drawn by stalemate with the King in the corner, threefold repetition or the 50-move rule, it may be drawn by allowing promotion and trading down to just the two Kings.",
    ["G4xdAsQl.c57"] = "If Black is allowed, they will promote.",
    ["G4xdAsQl.c6"] = "If Black blocks their own pawn instead of going to the corner, it's still a draw, it just takes longer. As White, we can try to use the technique we learned before. We use the free move to get our King closer.",
    ["G4xdAsQl.c8"] = "Pin the pawn.",
    ["G4xdAsQl.d"] = "If the pawn on the 7th rank is a Bishop or Rook pawn, and the side with the Queen does not have their King near the pawn, the side with the pawn can draw.\n\nWhen it's a Bishop pawn, the side with the pawn just needs to promote it if allowed, or threaten to promote it, or exploit the possible stalemate situation. If played correctly, the side with the Queen won't have any time to get their King closer.",
    ["G4xdAsQl.n"] = "Bishop pawn, no King assistance = Draw",
    ["GOhYTn1t.d"] = "Take the opposition to reach a key square and win!",
    ["GOhYTn1t.n"] = "Direct Opposition #3",
    ["HDj6qwSe.n"] = "Exercise: Checkmate the Engine - DSB Edition",
    ["HbKbCmjp.d"] = "If the pawn on the 7th rank is NOT a Bishop or Rook pawn, the side with the Queen can win.\n\nThe key to winning these positions is to get our King near the pawn so we can capture it safely. To do this, we must force Black to block their own pawn with their King. This will give us a free move which we can use to get our King closer.",
    ["HbKbCmjp.n"] = "Exercise: b-pawn = Win",
    ["HcO0b869.c1"] = "Before we can transition our Bishop to the second triangle by playing Ba4, we must further restrict the Black King. Start by taking away the f8 square.",
    ["HcO0b869.c11"] = "Black's area is shrinking. Invade further!",
    ["HcO0b869.c13"] = "Take the opposition.",
    ["HcO0b869.c15"] = "If you played Ba4 now, the King would escape to d5. Cover that square first.",
    ["HcO0b869.c17"] = "You still can't play Ba4 to transition to the second triangle. Take away more territory from the Black King. Avoid putting your King on d5, because that is where you want your Knight to end up.",
    ["HcO0b869.c19"] = "Ba4 is still not possible. One more King move will solve that problem.",
    ["HcO0b869.c21"] = "Finally, you can transition the Bishop safely without letting the Black King escape.",
    ["HcO0b869.c23"] = "The Knight doesn't have to cover b4 at the moment, so this is the perfect time to re-maneuver the Knight into the perfect square for the second triangle.",
    ["HcO0b869.c25"] = "Get the Knight into the perfect position for the second triangle, covering b6, c7 and e7.",
    ["HcO0b869.c27"] = "Your King must go back in order to push Black's King further towards the corner, otherwise it will shuffle back and forth on d8 and c8.",
    ["HcO0b869.c29"] = "Take away the d8 square",
    ["HcO0b869.c3"] = "Play a waiting move that will help you to force Black's King back.",
    ["HcO0b869.c31"] = "Set up the perfect Second Triangle by taking away the a6 square",
    ["HcO0b869.c32"] = "Nice work! The King is now restricted to the Second Triangle. Notice how we control all the red squares.",
    ["HcO0b869.c5"] = "Take away the e6 and e8 squares.",
    ["HcO0b869.c7"] = "Now invade with your King to take more territory.",
    ["HcO0b869.c9"] = "Since you can't invade further with your King at the moment, play another waiting move.",
    ["HcO0b869.n"] = "Restricting the King to the Second Triangle",
    ["HmvQuHx6.d"] = "In this position, white has a passive rook blocking the promotion square of the pawn, but is still able to win by trading rooks into a pawn endgame.",
    ["HmvQuHx6.n"] = "5 vs 4 - RP Passive Rook",
    ["IB4Pmsm6.d"] = "In the Dovetail Mate, the mating queen is one square diagonally from the mated king which escape is blocked by two friendly non-Knight pieces.",
    ["IB4Pmsm6.n"] = "Dovetail Mate #1",
    ["ICdDOPWR.d"] = "From Hugh Edward Myers - Dmitri Poliakoff, 1955.",
    ["ICdDOPWR.n"] = "Corner Mate #2",
    ["JGc9jW1b.d"] = "From Heinrich Ranneforth - Herbert Edward Dobell, 1903.",
    ["JGc9jW1b.n"] = "Double Bishop Mate #2",
    ["JJjS0WMm.c0"] = "An extra pawn on g3 has been introduced. What difference does it make? Well, if we push it to g6, it takes away the h7 square from Black's King.",
    ["JJjS0WMm.c1"] = "White has no threats, so Black shuffles.",
    ["JJjS0WMm.c15"] = "We are now threatening to move our Rook from the promotion square followed by a8=Q, so Black has to check our King away.",
    ["JJjS0WMm.c16"] = "Let's try to hunt down the Rook.",
    ["JJjS0WMm.c5"] = "Black can no longer shuffle their King because h7 is unavailable, but Black's King can still occupy g7 and Black can still do nothing by moving their Rook back and forth on the promotion file. Note that Kxg6 would be a losing blunder for Black due to Rg8+ followed by a8=Q.",
    ["JJjS0WMm.c6"] = "We can try to help our pawn with our King.",
    ["JJjS0WMm.n"] = "King on g7, extra g-pawn",
    ["Jg3nkOvR.c0"] = "There are some special cases where rook +2 connected passers vs rook is drawn. Here is one of them.\n\nHere, all what black needs to do is bring the king to help the pawns and the rook, but we can't cut off the king right away since h3 would be winning for black. Therefore white needs to create a threat first.",
    ["Jg3nkOvR.c1"] = "With this move, we force Black to play Rh2 to defend the pawn. If Black plays h3, we can get an easy draw with Rg4+ followed by Rxg3.",
    ["Jg3nkOvR.c11"] = "The idea is to play Rg4 if black moves the rook away.",
    ["Jg3nkOvR.c13"] = "We must keep the rook on either the h- or g- file so that the Black rook can't free itself.",
    ["Jg3nkOvR.c17"] = "The point: if black plays h3, g3 is hanging. Black can't make any progress.",
    ["Jg3nkOvR.c2"] = "Now we can cut off the king so it can't help the pawns and the rook since h3 wouldn't work due to Rb3.",
    ["Jg3nkOvR.c4"] = "Now we need to recreate the same threat.",
    ["Jg3nkOvR.c9"] = "Black's rook can't move away since black would lose the pawn.",
    ["Jg3nkOvR.n"] = "Kasparian's Draw",
    ["JmH1cznZ.d"] = "In the Arabian Mate, the knight and the rook team up to trap the opposing king on a corner of the board. The rook sits on a square adjacent to the king both to prevent escape along the diagonal and to deliver checkmate while the knight sits two squares away diagonally from the king to prevent escape on the square next to the king and to protect the rook.",
    ["JmH1cznZ.n"] = "Arabian Mate #1",
    ["JrrEF3jc.d"] = "When the pawn is on the seventh rank, the key squares are the squares on the seventh and eighth rank that touch the pawn's square. Reach a key square with your king and win.",
    ["JrrEF3jc.n"] = "Pawn on the 7th rank",
    ["JrzFnQwO.n"] = "Interference #2",
    ["JtUUH2sT.d"] = "From Paul Morphy - Schrufer, 1859.",
    ["JtUUH2sT.n"] = "Smothered Mate #4",
    ["K8Hmhh0e.c0"] = "Force the black King to block their own pawn or to step away from it.",
    ["K8Hmhh0e.c1"] = "Ka1 would lose after Kb3 c1=Q Qa4+ threatening an unstoppable Qa2#. Kc1 would lose after Qe1+ Kb2 Qd2 Kb1 Kb3 forcing a Knight promotion and eventual checkmate as we have seen before. Ka2 loses just as quickly, but let's see why.",
    ["K8Hmhh0e.c2"] = "Pin and threaten the pawn. Note that Qc3 would be a massive blunder because after c1=Q, Qxc1 would be stalemate.",
    ["K8Hmhh0e.c3"] = "Ka1 loses due to Kb3 Kb1 Qxc2+ Ka1 Qa2#. Kb2 loses because Kb4 Kb1 Kb3, forcing a Knight promotion and eventual checkmate. Kb1 is the best try.",
    ["K8Hmhh0e.c4"] = "Threaten checkmate.",
    ["K8Hmhh0e.c5"] = "Forcing c1=N+, as c1=Q would immediately lose due to Qa2#.",
    ["K8Hmhh0e.d"] = "If the pawn on the 7th rank is a Bishop pawn, and the side with the Queen has their King on one of the green squares on their move, they can win the game.\n\nThe side with the Queen can allow the pawn to promote and deliver checkmate. When both Kings are on the short side, the attacker can accomplish this by having their King on b3 when the pawn promotes.",
    ["K8Hmhh0e.n"] = "Bishop pawn, defending King on short side, King assistance on short side = Win",
    ["KZBNwdnP.d"] = "In Anderssen's mate, named for Adolf Anderssen, the rook or queen is supported by a diagonally-attacking piece such as a pawn or bishop as it checkmates the opposing king along the eighth rank.",
    ["KZBNwdnP.n"] = "Anderssen's Mate #1",
    ["Ka5DqXAD.d"] = "From Alexander Baburin - Utut Adianto, 1993.",
    ["Ka5DqXAD.n"] = "Damiano's Mate #3",
    ["L3kh6vbe.c0"] = "We covered all the Rook and Pawn vs Rook positions, the next 4 chapters are about a rook vs one or more pawns.\n\nThis position comes from Dvoretsky's endgames manual. The idea is to bring the king in a way that black's promotion to a queen doesn't come with a check, so white can checkmate black with the rook.",
    ["L3kh6vbe.c4"] = "White would still be winning even if black would have promoted to a knight with check.",
    ["L3kh6vbe.n"] = "A Position From Dvoretsky",
    ["MTv41MYN.d"] = "This 4 vs 3 is different - when the attacker can activate their rook behind the outside passer, the ending is usually won. Activate your king, force Black into concessions to stop the a-pawn, and then switch back to the kingside!\n\nA.Alekhine-J.Capablanca, Buenos Aires 1927",
    ["MTv41MYN.n"] = "4 vs 3 - RP Active Rook",
    ["NcEt7RJK.n"] = "Knight pawn on the 6th exception #2",
    ["Nm3PDybQ.d"] = "From Paul Keres - Robert James Fischer, 1959.",
    ["Nm3PDybQ.n"] = "Swallow's Tail Mate #2",
    ["NwYqcfEK.d"] = "Réti's Mate is named after Richard Réti, who delivered it in an 11-move game against Savielly Tartakower in 1910 in Vienna. It works by trapping the enemy king with four of its own pieces that are situated on flight squares and then attacking it with a bishop that is protected by a rook or queen.",
    ["NwYqcfEK.n"] = "Réti's Mate #1",
    ["NxKgWCZT.d"] = "If the pawn on the 7th rank is NOT a Bishop or Rook pawn, the side with the Queen can win.\n\nThe key to winning these positions is to get our King near the pawn so we can capture it safely. To do this, we must force Black to block their own pawn with their King. This will give us a free move which we can use to get our King closer.",
    ["NxKgWCZT.n"] = "Exercise: d-pawn = Win",
    ["O2aEY5v3.c0"] = "The first step is to get our Queen to d2. Black is threatening to promote, so we need to do it without losing any time.",
    ["O2aEY5v3.c1"] = "Kc1 would drop the pawn and lose immediately, so Black goes Ka1.",
    ["O2aEY5v3.c10"] = "Get the Queen back in position to set up the checkmate threats.",
    ["O2aEY5v3.c11"] = "Only one legal move.",
    ["O2aEY5v3.c13"] = "We have reached the goal position. Three checkmates in 1 are threatened. Note that Black can't check White without losing their Queen.",
    ["O2aEY5v3.c2"] = "Force the King out to the 7th rank.",
    ["O2aEY5v3.c4"] = "Get the Queen into position.",
    ["O2aEY5v3.c5"] = "Ka1 and Ka3 both lose instantly to checkmate in 1. After Kb1 we would play Kb4 and Black loses in a similar way to Kb3, but since Kb3 is slightly longer variation, let's look at that.",
    ["O2aEY5v3.c6"] = "Check the King back to the 7th rank so our King can get to b3.",
    ["O2aEY5v3.c8"] = "Now we can enter with our King.",
    ["O2aEY5v3.d"] = "If the pawn on the 7th rank is a Rook pawn, and the side with the Queen has their King on one of the green squares (or closer) on their move, they can win the game.\n\nThe side with the Queen can allow the pawn to promote and deliver checkmate. White can accomplish this by having their Queen on the d2 square (other squares can also work) and the King on b3 when the pawn has promoted.",
    ["O2aEY5v3.n"] = "Rook pawn, King assistance on short side = Win",
    ["O5xeONLS.d"] = "From an endgame composition by Goldberg, published in 1931.",
    ["O5xeONLS.n"] = "Zugzwang #4",
    ["OKzdXWrk.d"] = "From Ulvi Bajarani - Dragan Solak, 2010.",
    ["OKzdXWrk.n"] = "Damiano's Mate #2",
    ["ObmMRqmS.d"] = "A slightly trickier example, but the idea is the same. Cut off Black's king, reach the Lucena Position, and then either \"build the bridge\" or use the alternative winning method discussed in example #2.\n\nD.Andreikin-A.Korobov, Karpov Memorial 2016.",
    ["ObmMRqmS.n"] = "Reaching the Lucena II",
    ["Oky6VwLH.n"] = "Anastasia's Mate #3",
    ["OugIRn4J.d"] = "The Swallow's Tail Mate works by attacking the enemy king with a queen that is protected by a rook or other piece. The enemy king's own pieces block its means of escape. It is also known as the Guéridon Mate.",
    ["OugIRn4J.n"] = "Swallow's Tail Mate #1",
    ["OzAOZzTe.d"] = "From Juan Manuel Bellon Lopez - Jan Smejkal, 1970.",
    ["OzAOZzTe.n"] = "Dovetail Mate #3",
    ["PTdX46vW.c0"] = "When we reach the third triangle, our King and Bishop is restricting the enemy King which frees up our Knight to deliver mate.",
    ["PTdX46vW.n"] = "Delivering Mate",
    ["PlfyUKYK.d"] = "From Max Euwe - Wiersma, 1920.",
    ["PlfyUKYK.n"] = "Greco's Mate #2",
    ["PxLOgUGJ.d"] = "Louis Charles Mahe De La Bourdonnais - Alexander McDonnell, 1834.",
    ["PxLOgUGJ.n"] = "Clearance #5",
    ["Q83SoirS.d"] = "Use the Counter-Check tactic to win the game.\n\nRaimundo Garcia - Eduardo Figueroa, 1963.",
    ["Q83SoirS.n"] = "Counter-Check #3",
    ["QM4bu546.d"] = "In Boden's Mate, two attacking bishops on criss-crossing diagonals deliver mate to a king obstructed by friendly pieces, usually a rook and a pawn.",
    ["QM4bu546.n"] = "Boden's Mate #1",
    ["QP6WT68l.d"] = "White can take Direct Opposition, but is that the best move? Remember the key squares.",
    ["QP6WT68l.n"] = "As a means to an end",
    ["Qd2KyxdM.n"] = "Attraction #9",
    ["Qv7dQ2Nd.d"] = "From Sidney Paine Johnston - Frank James Marshall, 1899.",
    ["Qv7dQ2Nd.n"] = "Greco's Mate #3",
    ["RZ73c1eu.c0"] = "Force the black King to block their own pawn or to step away from it.",
    ["RZ73c1eu.c1"] = "Kc1 loses after Qc3 Kb1 Kd2, winning the pawn on the next move. Ka1 loses more slowly.",
    ["RZ73c1eu.c2"] = "March in and take the pawn.",
    ["RZ73c1eu.c3"] = "No matter what Black does, it's checkmate in 2.",
    ["RZ73c1eu.d"] = "If the pawn on the 7th rank is a Bishop pawn, and the side with the Queen has their King on one of the green squares on their move, they can win the game.\n\nThe side with the Queen can allow the pawn to promote and deliver checkmate. When the attacking King is on the long side, and the defending King is on the short side, the attacker can accomplish this by having their King on d2 when the pawn promotes.",
    ["RZ73c1eu.n"] = "Bishop pawn, defending King on short side, King assistance on long side = Win",
    ["RaDQLnsJ.d"] = "The Counter-Check is a powerful tactic that occurs when our king is in check, and we block that check while simultaneously giving a check to the opponent's king. This tactic can be useful to gain a tempo and eventually win the game, or to force trades.\n\nDaniel Abraham Yanofsky - Harry Golombek, 1951.",
    ["RaDQLnsJ.n"] = "Counter-Check #1",
    ["RqV1zTUB.d"] = "From Jiri Lechtynsky - Ludek Pachman, 1968.",
    ["RqV1zTUB.n"] = "Discovered Check #4",
    ["Rvbocqh6.d"] = "From Howard Staunton - Elijah Williams, 1851.",
    ["Rvbocqh6.n"] = "Vukovic Mate #2",
    ["S8rbDQmn.d"] = "With a king and pawn versus a lone king, it is important to get the attacking king to any key square and the path to a key square is not always direct. Reach a key square and win.",
    ["S8rbDQmn.n"] = "Any key square by any route",
    ["SFeb26xU.d"] = "The Corner Mate works by confining the king to the corner using a rook or queen and using a knight to engage the checkmate.",
    ["SFeb26xU.n"] = "Corner Mate #1",
    ["SJzGMHAr.d"] = "We know that an extra b-, c-, d-, e-, or f-pawn win for White. Force a win.",
    ["SJzGMHAr.n"] = "Exercise: King on g7, 2 vs 1 on the King-side",
    ["SX9Q3kbZ.d"] = "From Rudolf Spielmann - Ernst Gruenfeld, 1929.",
    ["SX9Q3kbZ.n"] = "Lolli's Mate #2",
    ["SmqmPeAV.n"] = "Attraction #5",
    ["THKE1CGV.d"] = "From John William Schulten - Bernhard Horwitz, 1846.",
    ["THKE1CGV.n"] = "Opera Mate #3",
    ["THRdWM26.d"] = "A missed tactic in Laszlo Szabo - Samuel Reshevsky, 1953.",
    ["THRdWM26.n"] = "Exploit the pin #4",
    ["Tb8Fd2nb.d"] = "From Rudolf Rezso Charousek - Jakob Wollner, 1893.",
    ["Tb8Fd2nb.n"] = "Double Check #3",
    ["TsCe5XET.d"] = "From Pavol Danek - Stanislav Hanuliak, 2001.",
    ["TsCe5XET.n"] = "Vukovic Mate #3",
    ["U3r4wkFn.d"] = "Use your queen to restrict the king, force it to the edge of the board and deliver checkmate. The queen can't do it alone, so use your king to help. Mate in 6 if played perfectly.",
    ["U3r4wkFn.n"] = "Queen mate",
    ["UH3RJjrN.d"] = "There are multiple solutions in this example, but use the X-Ray tactic to checkmate the opponent in 3 moves.\n\nZoltan Almasi - Viktor Korchnoi, 1996.",
    ["UH3RJjrN.n"] = "X-Ray #7",
    ["UZ1np9Is.n"] = "Double Bishop Mate #1",
    ["UtwzJ9i4.n"] = "Smothered Mate #2",
    ["V97iK4i2.c14"] = "Black is trying to restrict White's King from infiltrating Black's position. We can use the fact that Black's Rook has to stay on the promotion file to infiltrate with our King.",
    ["V97iK4i2.c23"] = "If Black goes Kf7, White can respond Kd6 and Black is in zugzwang.",
    ["V97iK4i2.c31"] = "...and we have an easily winning pawn endgame.",
    ["V97iK4i2.c7"] = "Note that Black can't play Rxg2, because we will then be able to promote our pawn.",
    ["V97iK4i2.d"] = "In this game, White did not force an e- or f-pawn, but rather sacrificed the a7 pawn to trade Rooks into a winning 4v4 pawn endgame. This is a useful concept to remember. From Bartholomew - Thaler, 2012.",
    ["V97iK4i2.n"] = "Bartholomew - Thaler, 2012: Trading into a winning 4v4 pawn endgame",
    ["VYSziBF5.d"] = "Use your queen and bishop to restrict the king and deliver checkmate. Mate in 5 if played perfectly.",
    ["VYSziBF5.n"] = "Queen and bishop mate",
    ["Vbpmd4lf.d"] = "A Triangle Mate is delivered by a queen attacking an enemy king, while it is supported by a rook. The queen and rook are one square away from the enemy king. They are on the same rank or file, separated by one square, with the enemy king being between them one square away, forming a triangle. The king must be restricted from escaping to the middle square behind it away from the queen and rook, by the edge of the board, a piece blocking it, or by controlling that square with a third piece.",
    ["Vbpmd4lf.n"] = "Triangle Mate #1",
    ["VeKiltmx.d"] = "Use your rook to restrict the king, force it to the edge of the board and deliver checkmate. The rook can't do it alone, so use your king to help. Mate in 11 if played perfectly.",
    ["VeKiltmx.n"] = "Rook mate",
    ["WGNZ2n0k.c0"] = "At first, this might look lost, as 1...Rg5 loses immediately to 2.Kd6. However, there is a way to hold this, with the Philidor idea of using the rook from behind. Bring the rook to f2 to continue the exercise.",
    ["WGNZ2n0k.c1"] = "Now we're getting ready to use the rook from behind to stop the pawn. Obviously Rf1 and Rf3 would have worked as well since it's the same idea.",
    ["WGNZ2n0k.c10"] = "Kg8 loses due to e6.",
    ["WGNZ2n0k.c16"] = "White is threatening checkmate.",
    ["WGNZ2n0k.c2"] = "In this position, we can't play Rd2+ since white can go to e6 and it would be hard to stop the pawn.\nAlso note that white is preparing Rh8+ followed by e6+ and e7, and the pawn would be unstoppable. Additionally, if after Rh8+ we get back the rook to f8 white can simply trade and play Kd7, which would again make the pawn unstoppable.\nWhat is the only move that stops white's threat?",
    ["WGNZ2n0k.c20"] = "Now we need to get back to our important squares before white prevents us from doing so.",
    ["WGNZ2n0k.c25"] = "White hasn't made any progress and the game will eventually end in a draw.",
    ["WGNZ2n0k.c3"] = "With this move, Rh8+ followed by e6+ is useless since the rook is now guarding the e6 square.",
    ["WGNZ2n0k.c8"] = "White realizes that the kingside is too short so they try to reroute the rook to a7.",
    ["WGNZ2n0k.n"] = "Advanced Philidor",
    ["WKTH4JFH.n"] = "Exercise: Checkmate the Engine",
    ["WV2JxGhI.d"] = "Smothered Mate occurs when a knight checkmates a king that is smothered (surrounded) by his friendly pieces and he has nowhere to move nor is there any way to capture the knight. It is also known as \"Philidor's Legacy\" after François-André Danican Philidor, though its documentation predates Philidor by several hundred years.",
    ["WV2JxGhI.n"] = "Smothered Mate #1",
    ["WjhSQVDH.d"] = "The name of this pattern was coined by Polish master Dawid Janowski, referring to coupled rooks on a player's 7th rank as swine. For this type of mate, the rooks on white's 7th rank can start out on any two of the files from a to e, and although black pawns are commonly present, they are not necessary to affect the mate.",
    ["WjhSQVDH.n"] = "Blind Swine Mate #1",
    ["WyWx7sFe.n"] = "Exercise: Checkmate the Engine - Rotated Edition",
    ["X6pXG1NK.d"] = "Morphy's Mate is named after Paul Morphy. It works by using the bishop to attack the enemy king while your rook and an enemy pawn helps to confine it.",
    ["X6pXG1NK.n"] = "Morphy's Mate #1",
    ["XOkS95uk.n"] = "Anastasia's Mate #2",
    ["XRgmISnM.d"] = "The Balestra Mate is similar to Boden's Mate, but instead of two bishops, a bishop and a queen is used. The bishop delivers the checkmate, while the queen blocks the remaining escape squares.",
    ["XRgmISnM.n"] = "Balestra Mate #1",
    ["XWE6mDll.c22"] = "Put Black in zugzwang.",
    ["XWE6mDll.c25"] = "Black doesn't want to move their Rook away from the promotion square, nor from protecting the e5 pawn. Kh6 would lose to Rh8+. Black could try Kh7, but after Kf5 g6+ Kf6, Black will eventually run out of moves and the Black Rook will be forced to move. In the game, Black moved their Rook immediately.",
    ["XWE6mDll.c33"] = "...and due to the e-pawn, we win as we have seen before.",
    ["XWE6mDll.d"] = "Due to the pawn on g7, White is unable to sacrifice the a7 pawn in order to trade Rooks. White can't force the trade of Rooks, but has to force an e- or f-pawn.",
    ["XWE6mDll.n"] = "Spassky - Torre, 1982: Forcing an e-pawn",
    ["XiaWAd1B.d"] = "Two knights can't force checkmate by themselves, but if the enemy has a pawn, we can avoid stalemate and force mate.\n\nMate in 15 if played perfectly.",
    ["XiaWAd1B.n"] = "Two knights vs pawn",
    ["XzIL7isq.d"] = "From Adolf Anderssen - Berthold Suhle, 1860.",
    ["XzIL7isq.n"] = "Pillsbury's Mate #2",
    ["Y63GFelK.d"] = "From Loek van Wely - Judit Polgar, 1997.",
    ["Y63GFelK.n"] = "Undermining #2",
    ["YAqTqI8s.c0"] = "The Vančura position is not a very common ending. It was studied by Josef Vančura and his analysis was published in 1924. The key idea is to keep giving lateral checks to drive White's king away from the queenside until white pushes the pawn to a7, then to play Ra6 to reach another well-known drawn rook ending.\n\nNote that in the Vančura position, we can't try to do checks from the 1st rank because white's king can hide on a7 and then white will be able to promote the pawn with the help of the rook.\n\nIn this position, we can start the sequence of checks with Rf5.",
    ["YAqTqI8s.c12"] = "Now we can bring the rook to a6 since white pushed the pawn to a7.",
    ["YAqTqI8s.c13"] = "And we have reached a well-known drawn rook endgame.",
    ["YAqTqI8s.c2"] = "White's king is getting closer to help the pawn promote, but it doesn't have any shelter on the queenside for the moment so we can just chase it away.",
    ["YAqTqI8s.c8"] = "We can continue with the same idea.",
    ["YAqTqI8s.c9"] = "If white's king gets back to the queenside, we can just continue our checks and white would not make any progress.",
    ["YAqTqI8s.d"] = "In this Study, we'll cover some more advanced forms of the rook and pawn versus rook endgame (Vancura Postion, Long Side Defense, Frontal Defense, Back Rank Defense against knight pawns, Rook pawn endgames, Advanced Philidor) as well as some endgames featuring a lone rook against one or more pawns highlighting tricky resources along the way.",
    ["YAqTqI8s.n"] = "Vancura Position",
    ["YAqTqI8s.w1.f6b6"] = "Also leads to a draw, but play Rf5 to continue the exercise.",
    ["YAqTqI8s.w1.g7h7"] = "Also leads to a draw, but play Rf5 to continue the exercise.",
    ["YAqTqI8s.w11.f5f4"] = "This position is deceptively tricky. While Rf6 in general is where we want the rook in the Vancura, in this position it is actually forced because if Black plays 6...Rf4+ then white will have the amazing resource 7.Ke5 Rf6 8.Rg8+! simplifying into a winning pawn endgame.",
    ["YAqTqI8s.w9.g7h7"] = "Also leads to a draw, but play Rf5 to continue the exercise.",
    ["YWsqVJDL.d"] = "From Josef Emil Krejcik - Julius Thirring, 1898.",
    ["YWsqVJDL.n"] = "Opera Mate #2",
    ["YaWQ1zCY.c0"] = "Get your Queen closer to the black King and pawn, without letting Black promote.",
    ["YaWQ1zCY.c1"] = "Black does not want to block their own pawn from promoting. That would give White a free move to bring their King closer.",
    ["YaWQ1zCY.c10"] = "We repeat the technique. Force the black King to block their own pawn or to step away from it.",
    ["YaWQ1zCY.c12"] = "Threaten the pawn.",
    ["YaWQ1zCY.c14"] = "We check the King and attack the pawn at the same time.",
    ["YaWQ1zCY.c16"] = "White gains another free move!",
    ["YaWQ1zCY.c18"] = "Pin!",
    ["YaWQ1zCY.c2"] = "We threaten the pawn.",
    ["YaWQ1zCY.c20"] = "Force the black King to block their own pawn or to step away from it.",
    ["YaWQ1zCY.c22"] = "Threaten the pawn.",
    ["YaWQ1zCY.c24"] = "We check the King and attack the pawn at the same time.",
    ["YaWQ1zCY.c26"] = "White gains another free move!",
    ["YaWQ1zCY.c28"] = "Pin!",
    ["YaWQ1zCY.c3"] = "Exactly! Black has to defend the pawn in the only way they can.",
    ["YaWQ1zCY.c30"] = "Force the black King to block their own pawn or to step away from it.",
    ["YaWQ1zCY.c32"] = "Threaten the pawn.",
    ["YaWQ1zCY.c34"] = "We check the King and attack the pawn at the same time.",
    ["YaWQ1zCY.c36"] = "White gains another free move!",
    ["YaWQ1zCY.c38"] = "Here we normally pin the pawn to the King, but because our King is close, we can actually force Black to block their own pawn more quickly.",
    ["YaWQ1zCY.c39"] = "If Black abandons the pawn with Kc1, we win easily. Black may therefore block their own pawn again.",
    ["YaWQ1zCY.c4"] = "Now we check the King and attack the pawn at the same time.",
    ["YaWQ1zCY.c40"] = "White gains another free move! Many moves including Ke3, win for White, but let's be as efficient as possible.",
    ["YaWQ1zCY.c42"] = "Mate in 2!",
    ["YaWQ1zCY.c44"] = "Mate in 1!",
    ["YaWQ1zCY.c5"] = "This forces Black to block their own pawn, as Kc1 which is the only other legal move would lose the pawn immediately.",
    ["YaWQ1zCY.c6"] = "Now we have gained a free move! What should we do with it?",
    ["YaWQ1zCY.c7"] = "Exactly, we bring the King closer. Now, Black only has two legal moves. Stepping into the pin with Kf1 gives White another free move immediately, so Black will normally play Kf2.",
    ["YaWQ1zCY.c8"] = "Many moves are winning for White, but the most efficient technique is to pin the pawn to the King.",
    ["YaWQ1zCY.d"] = "If the pawn on the 7th rank is NOT a Bishop or Rook pawn, the side with the Queen can win.\n\nThe key to winning these positions is to get our King near the pawn so we can capture it safely. To do this, we must force Black to block their own pawn with their King. This will give us a free move which we can use to get our King closer.",
    ["YaWQ1zCY.n"] = "Not a Bishop or Rook pawn = Win",
    ["YdrYt5v6.d"] = "From Gioachino Greco vs NN, 1620.",
    ["YdrYt5v6.n"] = "Pawn Mate #2",
    ["Z9gmSew0.c143"] = "White has reached the Knight and Bishop versus lone king endgame. With perfect play, this is mate in 24.",
    ["Z9gmSew0.c251"] = "Black claimed a draw due to the 50 move rule, 1/2 - 1/2",
    ["Z9gmSew0.d"] = "KBN vs K is a fairly rare endgame. A 2001 study showed that it happens in about 0.02% of games. Even so, it can be useful to study because the technique is hard to find OTB as this game shows.\n\nThis game took place in Geneva, Switzerland in 2013. It was Round 4 in a FIDE Women Grand Prix tournament. The Women's World Chess Champion, Anna Ushenina, failed to mate with Knight and Bishop and her opponent claimed a draw due to the 50 move rule.\n\nThe relevant part of the game starts at 72. Nxc3. Scroll through the moves and watch the video below. Move on to the next chapter when you're ready.",
    ["Z9gmSew0.n"] = "Epic Failure",
    ["ZPw4FLdV.d"] = "Here you can use Zugzwang to force checkmate. How cool is that?",
    ["ZPw4FLdV.n"] = "Zugzwang #2",
    ["ZiewgR9i.d"] = "Take the opposition to reach a key square and win!",
    ["ZiewgR9i.n"] = "Direct Opposition #4",
    ["ZkZ3w5gk.d"] = "Take the Distant Opposition to win the game.",
    ["ZkZ3w5gk.n"] = "Distant Opposition #2",
    ["ZtcsDndf.d"] = "If the pawn is on the second, third, or fourth rank, there are three key squares: the square two squares in front of the pawn and the squares to the left and right of that square. Reach a key square with your king and win.",
    ["ZtcsDndf.n"] = "Pawn on the 3rd rank",
    ["ZzwrrDey.c0"] = "The first step is to get our Queen to d2. Black is threatening to promote, so we need to do it without losing any time.",
    ["ZzwrrDey.c1"] = "Kc1 would drop the pawn and lose immediately, so Black goes Ka1.",
    ["ZzwrrDey.c2"] = "Force the King out to the 7th rank.",
    ["ZzwrrDey.c4"] = "Get the Queen into position.",
    ["ZzwrrDey.c6"] = "Now we can enter with our King.",
    ["ZzwrrDey.c7"] = "White has reached the goal position.",
    ["ZzwrrDey.c8"] = "Black has to promote to a Knight to avoid Qc2#, but it just delays the inevitable.",
    ["ZzwrrDey.d"] = "If the pawn on the 7th rank is a Rook pawn, and the side with the Queen has their King on one of the green squares (or closer) on their move, they can win the game.\n\nThe side with the Queen can allow the pawn to promote and deliver checkmate. White can accomplish this by having their Queen on the d2 square (other squares can also work) and the King on one of the orange squares (d3, d2, d1) when the pawn has promoted.",
    ["ZzwrrDey.n"] = "Rook pawn, King assistance on long side = Win",
    ["aBWil3J3.d"] = "From Ian Nepomniachtchi - Ivan Salgado Lopez, 2008.",
    ["aBWil3J3.n"] = "Hook Mate #3",
    ["aX3ICqvq.c0"] = "To draw this position as Black we keep our King on g7 or h7, and we keep our Rook on the promotion file whenever we can. If White moves their King next to their pawn we have to check it away.\n\nRight now, White isn't threatening anything, so we can just shuffle our King between g7 and h7.",
    ["aX3ICqvq.c10"] = "Our Rook is threatened, so we move it away while keeping it on the promotion file.",
    ["aX3ICqvq.c12"] = "White has no threats, so we keep shuffling.",
    ["aX3ICqvq.c16"] = "Our Rook is threatened, so we move it away while keeping it on the promotion file.",
    ["aX3ICqvq.c18"] = "White is now protecting their pawn and threatens to move their Rook away from the promotion square, followed by a8=Q. Continuing to shuffle with Kg7 would be a losing blunder for Black. Instead, we have to check White's King away from the pawn.",
    ["aX3ICqvq.c20"] = "We stay on the promotion file when we can.",
    ["aX3ICqvq.c22"] = "White has no threats, so we keep shuffling.",
    ["aX3ICqvq.c24"] = "White has no threats, so we keep shuffling.",
    ["aX3ICqvq.c26"] = "Our Rook is threatened, so we move it away while keeping it on the promotion file.",
    ["aX3ICqvq.d"] = "If Black's King is on any of the red squares when it's White to move, this position is a draw.\n\nWith Black's King on b6 or b7, Black will simply capture the pawn on the next move.\n\nWith Black's King on c6 or c7, Black will play Kb7 on the next move and be able to either capture the pawn or occupy the promotion square by playing Ka8.\n\nWith Black's King on a1, a2, or a6, it's impossible for White to move their Rook away from the promotion square with tempo as no checks are available. White either has to move their Rook and lose the pawn, or move their King. The White King has nowhere to hide, so black can just check White forever.\n\nIf the black King is on any square other than the red squares, it is a win for White.\n\nWith Black's King on d7, e7 or f7, White can play Rh8. Black can't respond with Rxa7 due to Rh7+, winning the rook on a7. The best Black can do is to delay the eventual loss.\n\nWith Black's King on any other square not mentioned, White can move their Rook away from the promotion square with a check and promote their pawn on the next move.",
    ["aX3ICqvq.n"] = "King on g7",
    ["awTDCajJ.d"] = "Max Lange's Mate is named after German chess player and problem composer Max Lange. It works by using the bishop and queen in combination to checkmate the king.",
    ["awTDCajJ.n"] = "Max Lange's Mate #1",
    ["bR4NLfKV.d"] = "Perhaps better referred to as a Corridor Mate rather than a Back-Rank Mate, it's still the same principle.",
    ["bR4NLfKV.n"] = "Back-Rank Mate #3",
    ["cIJ8kuxD.d"] = "If the pawn on the 7th rank is a Rook pawn, and the side with the Queen has their King on one of the green squares (or closer) on their move, they can win the game.\n\nThe side with the Queen can allow the pawn to promote and deliver checkmate. White can accomplish this by having their Queen on the d2 square (other squares can also work) and the King on b3 when the pawn has promoted.",
    ["cIJ8kuxD.n"] = "Exercise: Rook pawn, King assistance on short side",
    ["cUI6AYz4.d"] = "From Vassily Ivanchuk - Levon Aronian, 2013.",
    ["cUI6AYz4.n"] = "Hook Mate #2",
    ["ceGQbK3C.c0"] = "Currently, black isn't threatening anything, so we can play a waiting move. Play Ra3 to continue the exercise.",
    ["ceGQbK3C.c16"] = "The white king cannot move so if you give the rook the game will end in a stalemate.",
    ["ceGQbK3C.c4"] = "Black is threatening Rg1+.",
    ["ceGQbK3C.c6"] = "Bring the rook to b4 to attack the g4 pawn.",
    ["ceGQbK3C.n"] = "R2p vs R - Stalemate Trick",
    ["ceGQbK3C.w17.b4g4"] = "This doesn't work because black can capture with the Rook and it won't be a stalemate.",
    ["cf1cDFut.d"] = "From Schwartz - Carl Hartlaub, 1918.",
    ["cf1cDFut.n"] = "Double Check #1",
    ["cgZzXWz6.d"] = "Try to reach a Lucena position without accidentally running into a Philidor position. You can do this!",
    ["cgZzXWz6.n"] = "Avoiding the Philidor",
    ["dW7KIuoY.d"] = "Use your queen and rook to restrict the king and deliver checkmate. Mate in 3 if played perfectly.",
    ["dW7KIuoY.n"] = "Queen and rook mate",
    ["dkyqC39B.d"] = "Of the basic checkmates, this is the most difficult one to force, because the knight and bishop cannot form a linear barrier to the enemy king from a distance. The checkmate can be forced only in a corner that the bishop controls. The mating process often requires accurate play, since a few errors could result in a draw either by the fifty-move rule or stalemate.\n\nMate in 19 if played perfectly.",
    ["dkyqC39B.n"] = "Knight and bishop mate #2",
    ["duxBgZ8t.d"] = "Force the enemy king to the edge of the board while avoiding tricky knight forks. Mate in 12 if played perfectly.",
    ["duxBgZ8t.n"] = "Queen vs knight mate",
    ["eNlmabX1.d"] = "Direct Opposition is a position in which the kings are on the same rank or file and they are separated by one square. In such a situation, the player not having to move is said to \"have the opposition\". The side without the opposition may have to move the king away, potentially allowing the opposing king access to important squares. Take the opposition to reach a key square and win!",
    ["eNlmabX1.n"] = "Direct Opposition #1",
    ["ePgfuTan.d"] = "Cozio's Mate is an upside down version of the Dovetail Mate. It was named after a study by Carlo Cozio that was published in 1766.",
    ["ePgfuTan.n"] = "Cozio's Mate #1",
    ["eV7QCt5z.d"] = "If the pawn on the 7th rank is a Bishop pawn, and the side with the Queen has their King on one of the green squares on their move, they can win the game.\n\nThe side with the Queen can allow the pawn to promote and deliver checkmate. When the attacking King is on the long side, and the defending King is on the short side, the attacker can accomplish this by having their King on d2 when the pawn promotes.",
    ["eV7QCt5z.n"] = "Exercise: Bishop pawn, defending King on short side, King assistance on long sid",
    ["faSqpc3z.d"] = "From Vassily Ivanchuk - Levon Aronian, 2006.",
    ["faSqpc3z.n"] = "Blind Swine Mate #3",
    ["fkBWnQYv.d"] = "From Wilhelm Steinitz - J B Brockenbrough, 1885.",
    ["fkBWnQYv.n"] = "Suffocation Mate #2",
    ["gMOaAtuK.d"] = "Underpromoting means promoting a pawn to a piece with a lower value than a queen (rook, bishop and knight). Underpromoting can be useful to deliver a checkmate, prevent a stalemate, prevent a checkmate or in certain cases, gain a material advantage.\n\nWe usually underpromote to a bishop or rook only to prevent stalemate since the queen can move the same way as the two pieces combined, while underpromoting to a knight can be used for all the reasons stated above.",
    ["gMOaAtuK.n"] = "Introduction",
    ["gVXHdQCS.d"] = "Use your knowledge of Direct Opposition to win the game.",
    ["gVXHdQCS.n"] = "Direct Opposition #5",
    ["gZK2hI5S.d"] = "From Georges Koltanowski - Arthur Dunkelblum, 1923.",
    ["gZK2hI5S.n"] = "Double Check #2",
    ["gxmjAFU3.d"] = "From Gioachino Greco - NN, 1620.",
    ["gxmjAFU3.n"] = "Dovetail Mate #2",
    ["h7wbGw0s.d"] = "From Victor Kahn - Carl Hartlaub, 1916.",
    ["h7wbGw0s.n"] = "Double Bishop Mate #3",
    ["hg6wz0gX.d"] = "In the case where White has a central or bishop's pawn there is an alternative winning method: to maneuver the rook to the g8-square and budge Black's rook from that file, then simply marching forward with the king until there are no checks left. Be careful to not allow the rook to skewer the king and pawn!\n\nH.Ni-N.Pert, Liverpool 2007.",
    ["hg6wz0gX.n"] = "Lucena - Alternative Wins",
    ["hrOXELq2.c8"] = "White will promote the pawn and win the game.",
    ["hrOXELq2.n"] = "4 vs 4 - A trick",
    ["hrOXELq2.w5.g1f2"] = "This also wins but play Kh2 to continue the exercise.",
    ["i3Z6Yb3p.n"] = "Back-Rank Mate #2",
    ["iBm9kQPO.d"] = "From Rudolf Swiderski - Aron Nimzowitsch, 1905.",
    ["iBm9kQPO.n"] = "Blind Swine Mate #2",
    ["iC8DBiW6.d"] = "There is an exception to the key squares rule when a knight pawn is on its sixth rank, and the defending king is in the corner. Avoid the stalemate trick and win.",
    ["iC8DBiW6.n"] = "Knight pawn on the 6th exception #1",
    ["iNae4wci.d"] = "Blackburne's Mate is named for Joseph Henry Blackburne. This checkmate utilizes an enemy rook (or bishop or queen) to confine the black king's escape to the f8 square. One of the bishops confines the black king's movement by operating at a distance, while the knight and the other bishop operate within close range.",
    ["iNae4wci.n"] = "Blackburne's Mate #1",
    ["ijzggom5.d"] = "In this position, promoting to a queen or rook would result in an immediate stalemate, and promoting to a knight would be insignificant. Therefore, the only winning move for black is to promote to a bishop.",
    ["ijzggom5.n"] = "Underpromotion #5",
    ["jYURSgPr.c0"] = "We attempt to force an f-pawn, which we know would be winning for us.",
    ["jYURSgPr.c10"] = "Since Black's King is restricted to g7 and h7, and Black's Rook is restricted to the a-file, we can start marching our King to take f5.",
    ["jYURSgPr.c2"] = "gxh4+ was played in the game, but g4 would have drawn for Black as there would be no way to force an f-pawn anymore.",
    ["jYURSgPr.c20"] = "Note that Black has to stay on the promotion file with their Rook.",
    ["jYURSgPr.c34"] = "Put Black in zugzwang.",
    ["jYURSgPr.c35"] = "Kh6 is the only legal King move, and it loses to Rh8#. This means Black has to move their Rook away from protecting the f5 pawn, or away from protecting the promotion file.",
    ["jYURSgPr.c38"] = "We can now make way for our f-pawn which will force Black's king away from g7 and h7.",
    ["jYURSgPr.c4"] = "Ra4+ was played in the game, but f4 would still have saved the draw for Black as White would no longer be able to win Black's f-pawn. Why? Because with the Black pawn on f4, White can no longer zugzwang Black's Rook away from protecting the pawn, which is what happens later in the game continuation.",
    ["jYURSgPr.c49"] = "Moving away from g7 loses in the different ways we have seen before. Congratulations!",
    ["jYURSgPr.c6"] = "Kf6 was another missed opportunity for Black to play f4. Now we get to play it, instead.",
    ["jYURSgPr.c8"] = "We enter the familiar 7th rank Rook pawn position, forcing Black's King to g7 or h7 (in order to prevent White from playing Rh8).",
    ["jYURSgPr.d"] = "In this game, White forced an f-pawn and won the game. From \"Hochstrasser - Papa, Swiss National Championship A, 2012\".",
    ["jYURSgPr.n"] = "Hochstrasser - Papa, 2012: Forcing an f-pawn",
    ["jyR0zN5b.d"] = "The case where the attacker is up connected knight & rook pawns is much trickier to convert due to stalemate motifs popping up in the final phase. Avoid them and bring home the whole point!\n\nL.Aronian-F.Caruana, Norway Blitz 2015",
    ["jyR0zN5b.n"] = "R2p vs R - g & h-pawns",
    ["jzl2Iph1.d"] = "From Alexander Grischuk - Ruslan Ponomariov, 2000.",
    ["jzl2Iph1.n"] = "Smothered Mate #3",
    ["knauhco4.d"] = "Mikhail Chigorin - Eugene Znosko-Borovsky, 1903.",
    ["knauhco4.n"] = "X-Ray #4",
    ["mXNCYwCt.c0"] = "In the previous chapter, Black replied to Nf7+ with Kh7. Here, Black replies Kg8 instead. Based on what we have learned so far, what move should White now play?",
    ["mXNCYwCt.c1"] = "Correct! In the previous chapter, after Nf7+ Kh7 we played Bd5 as a waiting move in order to force Kg8. Since Black played Kg8 willingly, we can immediately play Kg6 Kf8 and reroute our Knight to d3.",
    ["mXNCYwCt.h0"] = "We want to force Black's king into the First Triangle",
    ["mXNCYwCt.n"] = "Exercise: Restricting the King to the First Triangle",
    ["mXNCYwCt.v1"] = "Incorrect! Take away the h7 square using your King.",
    ["mXNCYwCt.w1.c4d5"] = "This move also wins, but is not the move I was looking for. It is not necessary to play a waiting move now that Black volunteerily played Kg8.",
    ["mho3OpmO.d"] = "From Milorad Kapelan - James Tarjan, 1983.",
    ["mho3OpmO.n"] = "Double Check #4",
    ["mjgt4tfT.d"] = "From Isidor Gunsberg - Emil Schallopp, 1886.",
    ["mjgt4tfT.n"] = "Anderssen's Mate #2",
    ["moDJzyzD.d"] = "Peter Svidler - Boris Gelfand, 2009.",
    ["moDJzyzD.n"] = "X-Ray #2",
    ["mvDyziBk.d"] = "If the pawn on the 7th rank is a Rook pawn, and the side with the Queen has their King on one of the green squares (or closer) on their move, they can win the game.\n\nThe side with the Queen can allow the pawn to promote and deliver checkmate. White can accomplish this by having their Queen on the d2 square (other squares can also work) and the King on one of the orange squares (d3, d2, d1) when the pawn has promoted.",
    ["mvDyziBk.n"] = "Exercise: Rook pawn, King assistance on long side",
    ["n76eNBSa.d"] = "From William Norwood Potter - Matthews, 1868.",
    ["n76eNBSa.n"] = "Discovered Check #2",
    ["n9DF8U7O.c0"] = "This is a very well-known study named after Fernando Saavedra. Try to solve it!",
    ["n9DF8U7O.c10"] = "Kb3 and Kc3 work here as well here but it would transfer to the same position.",
    ["n9DF8U7O.c13"] = "White is winning.",
    ["n9DF8U7O.n"] = "A study by Saavedra",
    ["nFpZYIhC.d"] = "Pillsbury's Mate is named for Harry Nelson Pillsbury and is a variation of Morphy's Mate. The rook delivers checkmate while the bishop prevents the King from fleeing to the corner square.",
    ["nFpZYIhC.n"] = "Pillsbury's Mate #1",
    ["o3Hq4RZ0.d"] = "If the pawn is on the second, third, or fourth rank, there are three key squares: the square two squares in front of the pawn and the squares to the left and right of that square. Reach a key square with your king and win.",
    ["o3Hq4RZ0.n"] = "Pawn on the 2nd rank",
    ["oodwUwS7.d"] = "When you're up two connected central pawns, the win is not difficult. Prove it!\n\nV.Gashimov-A.Morozevich, World Blitz Championships 2009",
    ["oodwUwS7.n"] = "R2p vs R - Central Pawns",
    ["p1EQFuin.d"] = "Lolli's Mate involves infiltrating Black's fianchetto position using both a pawn and queen. The queen often gets to the h6 square by means of sacrifices on the h-file. It is named after Giambattista Lolli.",
    ["p1EQFuin.n"] = "Lolli's Mate #1",
    ["p2mcIgK7.d"] = "From Efim Bogoljubov - NN, 1952.",
    ["p2mcIgK7.n"] = "Greek Gift Challenge #1",
    ["p5fh4OFe.d"] = "From Magnus Carlsen - Sipke Ernst, 2004.",
    ["p5fh4OFe.n"] = "Epaulette Mate #3",
    ["pUZlG36u.c0"] = "At first glance, it looks like White may have lost this game, as Black's pawns have made it all the way to the 6th rank. However, there is one last drawing trick.",
    ["pUZlG36u.c1"] = "White tries to setup a mating net.",
    ["pUZlG36u.c10"] = "Black needs to keep preventing checkmate on h1, the game will eventually end in a draw.",
    ["pUZlG36u.c8"] = "Black needs to keep moving the king to not be mated. Kh2 wouldn't have worked due to Ra1 and Black would have been in zugzwang.",
    ["pUZlG36u.n"] = "A Tricky Resource",
    ["pUZlG36u.w7.g1h1"] = "Also draws, but play Kf3 to continue with the same idea of keeping threatening checks.",
    ["q5j2neYH.d"] = "Max Euwe - Rudolf Loman, 1923.",
    ["q5j2neYH.n"] = "X-Ray #3",
    ["qGAvVEjx.c0"] = "We start with the normal technique. Force the black King to block their own pawn or to step away from it.",
    ["qGAvVEjx.c10"] = "Reach the goal position.",
    ["qGAvVEjx.c11"] = "c1=Q would immediately lose to Qa2#, so Black is forced to promote to a Knight",
    ["qGAvVEjx.c14"] = "We could capture the Knight, but mate in 2 is better.",
    ["qGAvVEjx.c2"] = "Threaten the pawn.",
    ["qGAvVEjx.c4"] = "Check the King and attack the pawn at the same time.",
    ["qGAvVEjx.c6"] = "Use the free move to bring the King closer.",
    ["qGAvVEjx.c8"] = "Pin the pawn.",
    ["qGAvVEjx.c9"] = "Ka2 would drop the pawn immediately. Ka1 and Kb1 can be met the same way.",
    ["qGAvVEjx.d"] = "If the pawn on the 7th rank is a Bishop pawn, and the side with the Queen has their King on one of the green squares on their move, they can win the game.\n\nThe side with the Queen can allow the pawn to promote and deliver checkmate. When the attacking King is on the short side, and the defending King is on the long side, the attacker can accomplish this by having their King on b3 when the pawn promotes.",
    ["qGAvVEjx.n"] = "Bishop pawn, defending King on long side, King assistance on short side = Win",
    ["qSxvXGjA.n"] = "Attraction #4",
    ["qooQw3mQ.d"] = "Keep your pieces on the opposite color squares from the enemy bishop to stay safe. Use your queen to encroach on the king and look for double attacks. Mate in 10 if played perfectly.",
    ["qooQw3mQ.n"] = "Queen vs bishop mate",
    ["qr2pOlrL.d"] = "The Suffocation Mate works by using the knight to attack the enemy king and the bishop to confine the king's escape routes.",
    ["qr2pOlrL.n"] = "Suffocation Mate #1",
    ["qvNhB8Io.c0"] = "The key idea is to park the king on h7 and advance the g-pawn. If we try to advance the h-pawn we will actually be too slow.",
    ["qvNhB8Io.c7"] = "One of the two pawns will eventually promote to a queen.",
    ["qvNhB8Io.n"] = "Rook versus Two Pawns",
    ["qvNhB8Io.w1.g5g6"] = "Doesn't work due to the intermediate move Rh5+. Remember this resource!",
    ["qvNhB8Io.w3.g6g7"] = "This doesn't work because black's king will come to f5 just in time.",
    ["r1OiE0Zn.d"] = "We know that an extra b-, c-, d-, e-, or f-pawn win for White. Prove it.",
    ["r1OiE0Zn.n"] = "Exercise: King on g7, extra c-pawn",
    ["rfcRWU6x.d"] = "In this study, we're going to look at the endgame where one side has a Queen and the other side has a pawn on the 7th rank. We're going to look at the following situations:\n\n1) Queen in front of the pawn = Win\n2) Not a Bishop or Rook pawn = Win\n3) Rook or Bishop pawn without King assistance = Draw\n4) Rook or Bishop pawn with King assistance = Win\n\nLet's start with a simple exercise to prove a first point: If the Queen can get in front of the pawn, the side with the Queen will win.\n\nWin this game.",
    ["rfcRWU6x.n"] = "Exercise: Queen in front = Win",
    ["sS1RMgHu.n"] = "Attraction #3",
    ["tAcIEIbG.d"] = "In this Study, we're going to cover basic rook endgames such as Lucena and Philidor. We're also going to see some basic ideas such as placing our rook behind passed pawns. Finally, we'll analyze some positions with a lone rook vs a pawn.\n\nThis is the classic Lucena position. White is definitely winning, but has a major problem to solve: their king stands on the pawn's promotion square and currently can't move. Furthermore, even if it could, repeated rook checks from behind will force it back in front of the pawn. The next sequence, famously called \"building a bridge\", addresses those issues elegantly.\n\nThe idea is to bring the rook to e4 then come to g5 with the king to be able to stop repetitive checks from behind.\n\nAnalysis from B.Larsen-W.Browne, Las Palmas 1982.",
    ["tAcIEIbG.n"] = "Lucena - The Bridge",
    ["tLcHpjXr.d"] = "The Kill Box Mate occurs when a rook is next to the enemy king and supported by a queen that also blocks the king's escape squares. The rook and the queen catch the enemy king in a 3 by 3 \"kill box\".",
    ["tLcHpjXr.n"] = "Kill Box Mate #1",
    ["tpAofLQr.d"] = "Greco's Mate is named after the famous Italian checkmate cataloguer Gioachino Greco. It works by using the bishop to contain the black king by use of the black g-pawn and subsequently using the queen or a rook to checkmate the king by moving it to the edge of the board.",
    ["tpAofLQr.n"] = "Greco's Mate #1",
    ["uCdoXMPb.c1"] = "Before you can safely transition your Bishop to the third triangle by playing Ba6, you must further restrict the Black King. Restrict the Black King further in a way that does not allow Black to take the opposition.",
    ["uCdoXMPb.c11"] = "Congratulations! Notice how we control all the red squares.",
    ["uCdoXMPb.c3"] = "Take the opposition.",
    ["uCdoXMPb.c5"] = "Take the opposition.",
    ["uCdoXMPb.c7"] = "Transition your Bishop to the diagonal of the third triangle.",
    ["uCdoXMPb.c9"] = "Keep the Black King restricted, but don't lose your Bishop. Avoid the stalemate!",
    ["uCdoXMPb.n"] = "Restricting the King to the Third Triangle",
    ["uiBRODnb.d"] = "Aron G Reshko - Oleg Kaminsky, 1972.",
    ["uiBRODnb.n"] = "Underpromotion #6",
    ["ur0UWlqg.d"] = "In this example, Bxh6 is a winning move as well, but try to find a mate in 2 using the X-Ray tactic.\n\nSven Platzack - John van Baarle, 1967.",
    ["ur0UWlqg.n"] = "X-Ray #6",
    ["wEJ2P81l.n"] = "Deflection #5",
    ["x7ABY4Aj.d"] = "In this position Black is unable to stop White from reaching the Lucena Position. The idea for white is to keep black's king cut off and push the pawn in a way that they can always defend it with their king. See if you can reach the Lucena and \"build the bridge\"!\n\nJ.Steer-A.Szurkos, Budapest 2014",
    ["x7ABY4Aj.n"] = "Reaching the Lucena I",
    ["xTPNRilL.d"] = "Other variations of the Dovetail Mate can occur if a queen delivers mate by checking the king from a diagonally adjacent square while supported by a friendly piece and you also control the two potential escape squares with other pieces, typically a bishop.",
    ["xTPNRilL.n"] = "Dovetail Mate #4",
    ["y8aQqIjW.c0"] = "Black is threatening to promote. We need to get our Queen closer without losing any time.",
    ["y8aQqIjW.c10"] = "Shoulder the King to get closer to the pawn.",
    ["y8aQqIjW.c12"] = "Bring the King closer to threaten Qc2#.",
    ["y8aQqIjW.c13"] = "c1=Q would immediately lose to Qe2#. c1=N loses slightly more slowly. The relatively best option for Black is Ke1, but this also loses.",
    ["y8aQqIjW.c6"] = "Normally we would threaten the pawn with Qc3, which also works, but we can be even more efficient here, because our King is so close.",
    ["y8aQqIjW.c8"] = "Here we can actually afford to spend a move on getting the King closer. Do you see why?",
    ["y8aQqIjW.c9"] = "c1=Q would immediately lose to Qe2#. c1=N loses slightly more slowly. The relatively best option for Black is Kd2, but this also loses.",
    ["y8aQqIjW.d"] = "If the pawn on the 7th rank is a Bishop pawn, and the side with the Queen has their King on one of the green squares on their move, they can win the game.\n\nThe side with the Queen can allow the pawn to promote and deliver checkmate. When both Kings are on the long side, the attacker can accomplish this by having their King on one of the orange squares (f3, f2, f1) when the pawn promotes.",
    ["y8aQqIjW.n"] = "Bishop pawn, defending King on long side, King assistance on long side = Win",
    ["y8htrXez.d"] = "If the extra pawn is not a knight pawn, then passive defense does not work anymore. Tip: don't push your pawn right away, only do so if it comes with a check or when white's king is away from the promotion square.",
    ["y8htrXez.n"] = "When the Back Rank Defense doesn't work",
    ["yaW2Jv12.d"] = "From Rudolf Spielmann - Baldur Hoenlinger, 1929.",
    ["yaW2Jv12.n"] = "Anderssen's Mate #3",
    ["ybYJ9gNa.d"] = "The word \"Zugzwang\" comes from German, and means \"being forced to make a move\". A player is in Zugzwang when it's their turn and every possible move makes their position worse.\n\nIn the above example, if black would only move his king to c8 then Rook to the back rank would be check mate, you can force the king to c8 by simply taking away every other option.\n\nWhite to play, mate in 2.",
    ["ybYJ9gNa.n"] = "Zugzwang #1",
    ["ygAaFQNc.d"] = "The Opera Mate works by attacking the king on the back rank with a rook using a bishop to protect it. A pawn or other piece other than a knight of the enemy king's is used to restrict its movement. The checkmate was named after its implementation by Paul Morphy in 1858 at a game at the Paris opera against Duke Karl of Brunswick and Count Isouard, known as the \"The Opera Game\".",
    ["ygAaFQNc.n"] = "Opera Mate #1",
    ["ykzze7QW.d"] = "X-Ray attacks happen when a piece attacks or defends a square, through an enemy piece.",
    ["ykzze7QW.n"] = "X-Ray #1",
}
